    ('growth-and-development', 3, 'Beaty described Beaverton as being ''in a time of immense growth'' and said ''while growth is important, this should be balanced with sustainability.'' She invested proactively in the Purple Pipe reclaimed-water infrastructure to support future growth, championed sidewalk and transportation infrastructure investments ahead of demand, and supported annexations. This is neither a growth-limits stance nor pure deregulation, but proactive infrastructure investment to support responsible expansion — Chair 3.', ARRAY['https://medium.com/usmayors/meet-the-mayor-lacey-beaty-5ad15bc11951', 'https://en.wikipedia.org/wiki/Lacey_Beaty']::text[]),
    ('taxes', 2, 'Beaty raised Beaverton''s property tax rate from $4.23 to $4.62 per $1,000 assessed value in 2023 to address structural budget pressures. She explicitly stated that if expenses continue to outpace revenues, property tax levies will be necessary in the future — signaling willingness to raise taxes to fund public services rather than cut services. She oversaw budget cuts in 2025 as a fiscal necessity, not an ideological preference for smaller government. This willingness to raise taxes on property owners to fund existing and expanded services maps to Chair 2 (moderately raise taxes to fund existing services).', ARRAY['https://beavertonvalleytimes.com/2023/06/16/beaverton-raises-property-taxes-using-decades-old-oregon-laws/', 'https://katu.com/news/local/beaverton-faces-107-million-budget-shortfall-plans-cuts-to-police-and-public-works-library-street-repair-resident-portland-oregon-washington-county-finances-economy-consumer']::text[])
)
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources)
SELECT '6f4e9c86-1c23-4569-ad1a-7614463420f1'::uuid, ct.id, s.reasoning, s.sources
